ANNOTATIONS = [
    (1, 'before', '''沙箱设置面板。用 Tabs 分出模式 / 覆盖 / 配置 / 依赖四页，但**页签集合不是固定的**：依赖检查有错时只留依赖页、有警告时在模式页后面插依赖页。这种「页签随环境状态增减」的形态，比固定四页更接近真实排障流程——装不上沙箱的人第一件需要的不是模式选择，而是看依赖缺什么。'''),
    (15, 'before', '''`onComplete` 的签名里带 `display?: CommandResultDisplay`，这个可选参数是「回执要不要显示」的开关：选定模式时返回一句确认文案（正常显示），按 Esc 退出时返回 undefined 并显式给 `display: 'skip'`，避免在对话里留下一条「命令已取消」的噪音。'''),
    (21, 'before', '''三种模式是一个**扁平三选一**：auto-allow（开沙箱 + 自动放行 bash）、regular（开沙箱 + 正常权限）、disabled（不开）。注意它把「是否开沙箱」与「沙箱内的 bash 是否自动放行」这两个独立开关压成三档，是为了避免用户选出「开沙箱但 bash 也完全不走沙箱」这种自相矛盾的组合。'''),
    (29, 'before', '''当前状态不从上一次的选择里读，而是**每次渲染直接从 SandboxManager 问**。这保证面板显示的永远是系统真实状态——即使用户在别处改了配置（或配置文件被手改），打开面板也不会显示过时的值。'''),
    (40, 'before', '''`allowAllUnixSockets` 是唯一一个从设置了里直读的字段，用来决定要不要显示 socket 警告。语义是：如果用户已经明确允许所有 unix socket，那么「无法阻断 unix domain socket」这条警告就没有意义了，不该再吓他。'''),
    (42, 'before', '''`getCurrentMode` 的推导顺序体现优先级：**先判未启用**，再判自动放行，否则 regular。顺序不能反——未启用时 autoAllowBashIfSandboxed 可能还是上次留下的 true，若先判它就会把「已关闭」误显示成 auto-allow。'''),
    (54, 'before', '''`(current)` 标记是用 `color('success', theme)` 预渲染成一个**字符串**而不是 JSX 节点，因为它要拼进 label 字符串里。这是终端 UI 里少见的「颜色进字符串」做法，需要 theme 在手，所以它也是本组件唯一依赖 `useTheme` 的地方。'''),
    (61, 'before', '''三个 label 都是「基础文案 + 当前项才追加大括号标记」。这是单选列表的常用手法：不用额外的勾选列，标记直接进文案，选中态与焦点态就不会打架（焦点由 Select 画指针，选中由这里画标记）。'''),
    (85, 'before', '''「No Sandbox」前面用空心圆（U+25CB），另两档用对勾（U+2713）。语义上是「关闭」与「启用」的区别，视觉上也刻意不同——避免用户以为自己选中的是同一个东西。'''),
    (110, 'before', '''选定模式后调用 `setSandboxSettings` 写入两个字段，然后回一句确认。注意每档都**显式写全两个字段**，而不是只写变化的那一个：只写部分字段会让旧的 autoAllow 值残留下来，产生「关了沙箱但 autoAllow 还是 true」的脏状态。'''),
    (150, 'before', '''`confirm:no` 绑定（Esc / 选 No）走 `onComplete(undefined, { display: 'skip' })`。这是本组件与调用方的约定：**不返回文案 + 标记 skip**，调用方据此完全不渲染任何东西。若返回空字符串，对话里还会多一个空行。'''),
    (171, 'before', '''Mode 页把 options 与 onSelect 往下传，自己只负责外层 Tab 壳。注意它同时传了 `showSocketWarning`——警告是显示在**模式页顶部**的，因为「无法阻断 socket」这件事直接影响用户该不该选 auto-allow。'''),
    (198, 'before', '''依赖检查有 **errors** 时走完全不同的页签集合：只剩「Dependencies」一页。这意味着用户在这个状态下**无法**从界面上改模式——因为沙箱根本跑不起来，让他先选模式毫无意义。有 warnings 时则保留模式页、在它后面插依赖页（可以继续用，但建议修）。'''),
    (201, 'before', '''页签数组用一个三目整体构造：`hasErrors ? [只依赖页] : [模式页, ...(有警告 ? [依赖页] : []), 覆盖页, 配置页]`。中间的展开是「条件插入」，这种写法比 `if` 里 push 更紧凑，但要注意顺序——依赖页被特意放在模式页之后、覆盖页之前，因为它属于「先看清环境再配置」的那一步。'''),
    (214, 'before', '''`defaultTab=「Mode」` 是硬编码的默认页。所以**依赖有错时**用户进来会落到「不存在的 Mode 页」吗？不会——Tabs 组件在 defaultTab 不存在时会退到第一个页签，这也是为什么有错时把依赖页放在数组第一位而不是靠后。'''),
    (230, 'before', '''`useTabHeaderFocus` 让「焦点在页签栏」与「焦点在内容里」互斥：headerFocused 为真时 Select 被禁用（isDisabled），此时方向键交给 Tabs 切页；否则方向键在选项里移动。这是设计系统 Tabs 约定的协作方式，页面自己不用管键位冲突。'''),
    (261, 'before', '''`onUpFromFirstItem={focusHeader}`：在选项列表第一项再按上键，焦点**交还给页签栏**。这个「向上溢出即回上级」的约定在终端多级界面里是通用手势，缺了它用户就只能靠 Tab 键切页、或者以为卡住了。'''),
    (273, 'before', '''页脚说明只解释 auto-allow 一档，因为另外两档的语义分别由「regular permissions」与「No Sandbox」自明。凡是「三档里只有一档需要解释」的选项组，都值得把说明写成针对性的段落，而不是给三档各写一句对称的废话。'''),
]
